function motionShow(el){
  if(!el)return;const token=(el._motionToken||0)+1;el._motionToken=token;
  clearTimeout(el._motionTimer);el.hidden=false;el.classList.remove('motion-out');void el.offsetWidth;el.classList.add('motion-in');
  el._motionTimer=setTimeout(()=>{if(el._motionToken===token)el.classList.remove('motion-in')},760)
}
function motionHide(el,after){
  if(!el||el.hidden){after?.();return}const token=(el._motionToken||0)+1;el._motionToken=token;
  clearTimeout(el._motionTimer);el.classList.remove('motion-in');void el.offsetWidth;el.classList.add('motion-out');
  el._motionTimer=setTimeout(()=>{if(el._motionToken!==token)return;el.hidden=true;el.classList.remove('motion-out');after?.()},460)
}
function motionToggle(el){if(!el)return false;if(el.hidden||el.classList.contains('motion-out')){motionShow(el);return true}motionHide(el);return false}
let customizerOpenState=false,customizerAnimation=null,customizerAnimationSerial=0;
function setCustomizerOpen(open){
  const c=$('#customizer'),b=$('#customizeBtn');if(!c)return;
  open=!!open;customizerOpenState=open;b?.classList.toggle('active',open);
  const serial=++customizerAnimationSerial;
  const rect=c.getBoundingClientRect(),cs=getComputedStyle(c);
  const currentH=Math.max(0,rect.height),currentOpacity=Number.parseFloat(cs.opacity)||0,currentMargin=Number.parseFloat(cs.marginBottom)||0;
  const currentTransform=cs.transform==='none'?'translateY(0px) scale(1)':cs.transform;
  if(customizerAnimation){try{customizerAnimation.cancel()}catch{}customizerAnimation=null}
  c.style.height=currentH+'px';c.style.opacity=String(currentOpacity);c.style.marginBottom=currentMargin+'px';c.style.transform=currentTransform;
  c.style.visibility='visible';c.style.pointerEvents=open?'auto':'none';
  c.classList.toggle('open',open);c.classList.toggle('motion-opening',open);c.classList.toggle('motion-closing',!open);
  const targetH=open?Math.max(c.scrollHeight,currentH):0,targetOpacity=open?1:0,targetMargin=open?16:0;
  const frames=open?[
    {height:currentH+'px',opacity:currentOpacity,marginBottom:currentMargin+'px',transform:currentTransform,offset:0},
    {height:targetH+'px',opacity:1,marginBottom:'16px',transform:'translateY(2px) scale(1.003)',offset:.72},
    {height:targetH+'px',opacity:1,marginBottom:'16px',transform:'translateY(0) scale(1)',offset:1}
  ]:[
    {height:currentH+'px',opacity:currentOpacity,marginBottom:currentMargin+'px',transform:currentTransform,offset:0},
    {height:Math.max(0,currentH*.36)+'px',opacity:.58,marginBottom:Math.max(0,currentMargin*.36)+'px',transform:'translateY(-4px) scale(.997)',offset:.64},
    {height:'0px',opacity:0,marginBottom:'0px',transform:'translateY(-10px) scale(.992)',offset:1}
  ];
  customizerAnimation=c.animate(frames,{duration:1000,easing:'cubic-bezier(.16,1,.3,1)',fill:'forwards'});
  customizerAnimation.onfinish=()=>{
    if(serial!==customizerAnimationSerial)return;customizerAnimation=null;c.classList.remove('motion-opening','motion-closing');
    if(open){c.classList.add('open');c.style.height='auto';c.style.opacity='1';c.style.marginBottom='16px';c.style.transform='none';c.style.visibility='visible';c.style.pointerEvents='auto'}
    else{c.classList.remove('open');c.style.height='0px';c.style.opacity='0';c.style.marginBottom='0px';c.style.transform='translateY(-10px) scale(.992)';c.style.visibility='hidden';c.style.pointerEvents='none'}
  };
  customizerAnimation.oncancel=()=>{};
}
