function switchActiveList(id){
  if(!id||id===state.activeListId)return;
  const root=document.documentElement,oldBg=$('#appBackground');
  let bgClone=null;
  if(oldBg&&oldBg.childNodes.length){
    bgClone=oldBg.cloneNode(true);bgClone.removeAttribute('id');bgClone.className='bg-transition-old';
    bgClone.querySelectorAll('[id]').forEach(n=>n.removeAttribute('id'));document.body.appendChild(bgClone);
    bgClone.querySelectorAll('video').forEach(v=>{v.muted=true;v.loop=true;v.playsInline=true;try{v.play()}catch{}});
  }
  root.classList.add('list-morphing');
  state.activeListId=id;notesOpen=false;closePartsPopover(true);hidePartsHover(true);
  applyAll();render();
  board.classList.remove('list-morph-content');void board.offsetWidth;board.classList.add('list-morph-content');
  setTimeout(()=>board.classList.remove('list-morph-content'),820);
  if(bgClone){const a=bgClone.animate([{opacity:1},{opacity:0}],{duration:980,easing:'cubic-bezier(.22,1,.36,1)',fill:'forwards'});a.finished.finally(()=>bgClone.remove())}
  clearTimeout(switchActiveList._t);switchActiveList._t=setTimeout(()=>root.classList.remove('list-morphing'),1050);
  queueSave();
}
