function hidePartsHover(immediate=false){clearTimeout(partsHoverTimer);clearTimeout(partsHoverCloseTimer);partsHoverItemId=null;const p=$('#partsHoverPreview');if(!p)return;if(immediate){p.hidden=true;p.classList.remove('motion-in','motion-out');return}motionHide(p)}
function positionPartsHover(anchor,p=$('#partsHoverPreview')){
  if(!anchor||!p)return;const r=anchor.getBoundingClientRect(),pw=Math.min(310,window.innerWidth-24),fixed=!!anchor.closest('#notesPopover');
  p.style.position=fixed?'fixed':'absolute';p.style.width=pw+'px';p.hidden=false;
  const ph=Math.min(p.scrollHeight||280,window.innerHeight-24),barBottom=$('.topbar')?.getBoundingClientRect().bottom||12,safeTop=Math.max(12,barBottom+8);
  let left=r.right+12,side='right';if(left+pw>window.innerWidth-12){left=r.left-pw-12;side='left'}if(left<12){left=Math.max(12,Math.min(window.innerWidth-pw-12,r.left+r.width/2-pw/2));side='center'}
  let top=r.top+(r.height-ph)/2;top=Math.max(safeTop,Math.min(window.innerHeight-ph-12,top));
  const ox=fixed?0:window.scrollX,oy=fixed?0:window.scrollY;p.style.left=(left+ox)+'px';p.style.top=(top+oy)+'px';p.style.right='auto';p.classList.toggle('from-left',side==='left')
}
function renderPartsHover(item){const p=$('#partsHoverPreview'),list=$('#partsHoverList');$('#partsHoverParent').textContent=item.title;list.innerHTML='';(item.parts||[]).forEach((part,i)=>{const row=document.createElement('div');row.className='parts-hover-row';row.style.setProperty('--i',i);const thumb=document.createElement('div');thumb.className='parts-hover-thumb';if(part.media)thumb.appendChild(createMediaNode(part.media,part.mediaType||kindFromData(part.media)||'image',part.mediaMime||mimeFromData(part.media),'',true));else thumb.textContent=(part.title||'?').slice(0,2).toUpperCase();const main=document.createElement('div');main.innerHTML=`<div class="parts-hover-title">${esc(part.title)}</div>${part.note?`<div class="parts-hover-note">${esc(part.note)}</div>`:''}`;const rating=document.createElement('div');rating.className='parts-hover-rating';rating.textContent=part.rating||'—';row.append(thumb,main,rating);list.appendChild(row)});p.hidden=false}

