function openItem(id=null){editingItemId=id;const it=id?active().items[id]:null;$('#itemDialogTitle').textContent=it?tr('editItem'):tr('newItem');$('#itemTitle').value=it?.title||'';$('#itemAliases').value=(it?.aliases||[]).join(', ');$('#itemMedia').value='';$('#itemDestination').value='unranked';$('#destinationField').hidden=!!it;const w=$('#mediaPreviewWrap');w.innerHTML='';w.hidden=true;w.dataset.pending='';w.dataset.pendingType='';w.dataset.pendingMime='';if(it?.media)showPreview(it.media,it.mediaType||'image',it.mediaMime||mimeFromData(it.media),false);$('#itemDialog').showModal();setTimeout(()=>$('#itemTitle').focus(),0)}
function showPreview(src,type,mime,pending=true){const w=$('#mediaPreviewWrap');w.innerHTML='';const m=createMediaNode(src,type,mime,'',true);w.appendChild(m);const s=document.createElement('span');s.textContent=type==='video'?tr('videoSaved'):tr('mediaSaved');w.appendChild(s);w.hidden=false;if(pending){w.dataset.pending=src;w.dataset.pendingType=type;w.dataset.pendingMime=mime||''}}
function openTier(id=null){editingTierId=id;pendingTierBg=null;const t=id?active().tiers.find(x=>x.id===id):null;$('#tierName').value=t?.name||'';$('#tierColor').value=t?.color||'#ffcf66';$('#tierBg').value='';$('#tierDialog').showModal();setTimeout(()=>$('#tierName').focus(),0)}
function placeholder(title){const initials=(title||'?').slice(0,2).toUpperCase(),svg=`<svg xmlns="http://www.w3.org/2000/svg" width="300" height="420"><rect width="100%" height="100%" fill="#2b3240"/><text x="50%" y="50%" dominant-baseline="middle" text-anchor="middle" fill="#dce3ef" font-family="Arial" font-size="72" font-weight="700">${esc(initials)}</text></svg>`;return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg)}
const mimeMap={png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',jfif:'image/jpeg',webp:'image/webp',gif:'image/gif',bmp:'image/bmp',svg:'image/svg+xml',avif:'image/avif',heic:'image/heic',heif:'image/heif',mp4:'video/mp4',m4v:'video/x-m4v',mov:'video/quicktime',webm:'video/webm',ogv:'video/ogg',ogg:'video/ogg',avi:'video/x-msvideo',mkv:'video/x-matroska'};
const videoExt=new Set(['mp4','m4v','mov','webm','ogv','ogg','avi','mkv']);
function extOf(name){return (name||'').split('.').pop().toLowerCase()}
function guessMime(name){return mimeMap[extOf(name)]||''}
function mimeFromData(data){const m=/^data:([^;,]+)/.exec(data||'');return m?.[1]||''}
function kindFromData(data){const m=mimeFromData(data);return m.startsWith('video/')?'video':m.startsWith('image/')?'image':''}
function mediaInfo(f){const ext=extOf(f.name),mime=(f.type&&f.type!=='application/octet-stream'?f.type:guessMime(f.name))||'',kind=mime.startsWith('video/')||videoExt.has(ext)?'video':'image';return{kind,mime,name:f.name||''}}
function isExternalMediaFile(f){if(!f)return false;const i=mediaInfo(f),ext=extOf(f.name);return f.type?.startsWith('image/')||f.type?.startsWith('video/')||!!mimeMap[ext]||i.kind==='video'}
function fileToDataUrl(f){return new Promise((res,rej)=>{const info=mediaInfo(f),r=new FileReader();r.onerror=()=>rej(r.error);r.onload=()=>{let out=String(r.result||'');if(info.mime&&/^data:(application\/octet-stream)?;base64,/i.test(out))out=out.replace(/^data:(application\/octet-stream)?;base64,/i,`data:${info.mime};base64,`);res(out)};r.readAsDataURL(f)})}
const videoObjectUrlCache=new Map(),videoObjectUrls=new Set();
function shouldUseVideoBlobUrl(src){return typeof src==='string'&&src.startsWith('data:video/')&&src.length>1500000}
function getVideoObjectUrl(src){if(videoObjectUrlCache.has(src))return videoObjectUrlCache.get(src);const p=fetch(src).then(r=>{if(!r.ok)throw new Error('media decode');return r.blob()}).then(blob=>{const url=URL.createObjectURL(blob);videoObjectUrls.add(url);return url}).catch(err=>{videoObjectUrlCache.delete(src);throw err});videoObjectUrlCache.set(src,p);return p}
function assignVideoSource(v,src){if(!shouldUseVideoBlobUrl(src)){v.src=src;return}const token='v'+src.length+':'+src.slice(0,48);v.dataset.sourceToken=token;v.classList.add('media-loading');getVideoObjectUrl(src).then(url=>{if(v.dataset.sourceToken!==token)return;v.src=url;v.classList.remove('media-loading');v.load()}).catch(()=>{if(v.dataset.sourceToken===token){v.src=src;v.classList.remove('media-loading');v.load()}})}
function createMediaNode(src,kind,mime,cls='',background=false){if(kind==='video'){const v=document.createElement('video');if(cls)v.className=cls;v.muted=true;v.defaultMuted=true;v.playsInline=true;v.preload=background?'auto':'metadata';v.disablePictureInPicture=true;v.setAttribute('muted','');v.setAttribute('playsinline','');if(mime)v.dataset.mime=mime;if(background){v.loop=true;v.autoplay=true;const play=()=>attemptPlay(v);v.addEventListener('loadeddata',play,{once:true});v.addEventListener('canplay',play);v.addEventListener('playing',()=>v.classList.remove('media-loading'));setTimeout(play,0)}v.addEventListener('error',()=>showToast(tr('mediaPlaybackError')),{once:true});assignVideoSource(v,src);return v}const img=document.createElement('img');if(cls)img.className=cls;img.src=src;img.alt='';img.draggable=false;img.addEventListener('error',()=>showToast(tr('readFileError')),{once:true});return img}
function attemptPlay(v){if(!v)return;v.muted=true;v.defaultMuted=true;v.playsInline=true;const p=v.play();if(p?.catch)p.catch(()=>{})}
function rewindVideo(v){try{v.pause();if(v.readyState>=1&&Number.isFinite(v.duration))v.currentTime=0}catch{}}
function setupCardVideo(v,mode){if(!v)return;v.muted=true;v.defaultMuted=true;v.playsInline=true;v.controls=false;v.autoplay=false;v.onmouseenter=null;v.onmouseleave=null;const card=v.closest('.card');if(card){card.onmouseenter=null;card.onmouseleave=null}const whenReady=fn=>{if(v.readyState>=2)fn();else{v.addEventListener('loadeddata',fn,{once:true});v.addEventListener('canplay',fn,{once:true})}};if(mode==='loop'){v.preload='auto';v.loop=true;whenReady(()=>attemptPlay(v))}else if(mode==='hover'){v.preload='metadata';v.loop=true;whenReady(()=>rewindVideo(v));if(card){card.onmouseenter=()=>attemptPlay(v);card.onmouseleave=()=>rewindVideo(v)}}else{v.preload='metadata';v.loop=false;whenReady(()=>rewindVideo(v))}}
function applyVideoMode(){const mode=active().view.videoMode||'loop';$$('.card video.media').forEach(v=>setupCardVideo(v,mode))}
function checkMediaSize(f,input){const limit=25*1024*1024;if(f.size<=limit)return true;if(state.appSettings.allowLargeFiles){showToast(`${tr('largeFile')}: ${(f.size/1024/1024).toFixed(1)} MB`);return true}alert(tr('tooLarge'));if(input)input.value='';return false}

