$('#itemForm').addEventListener('submit',e=>{e.preventDefault();const title=$('#itemTitle').value.trim();if(!title)return;const aliases=$('#itemAliases').value.split(/[,;\n]+/).map(x=>x.trim()).filter(Boolean);const description=($('#itemDescription')?.value||'').trim();const l=active(),w=$('#mediaPreviewWrap'),p=w.dataset.pending,pt=w.dataset.pendingType,pm=w.dataset.pendingMime;let createdId=null;if(editingItemId&&l.items[editingItemId]){l.items[editingItemId].title=title;l.items[editingItemId].aliases=aliases;l.items[editingItemId].description=description;if(p)Object.assign(l.items[editingItemId],{media:p,mediaType:pt,mediaMime:pm})}else{const id=crypto.randomUUID();createdId=id;l.items[id]={id,title,aliases,description,media:p||'',mediaType:pt||'image',mediaMime:pm||'',parts:[]};($('#itemDestination').value==='notes'?l.notes:l.unranked).push(id)}if(createdId)pendingEntrance={kind:'item',id:createdId};$('#itemDialog').close();queueSave();render()});
$('#partMedia').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;if(!isExternalMediaFile(f)){alert(tr('unsupportedFile'));e.target.value='';return}if(!checkMediaSize(f,e.target))return;try{const info=mediaInfo(f),data=await fileToDataUrl(f);showPartPreview(data,info.kind,info.mime,true)}catch(err){console.error(err);showToast(tr('readFileError'))}});
$('#partForm').addEventListener('submit',e=>{e.preventDefault();const item=active().items[partsOpenItemId];if(!item)return;const title=$('#partName').value.trim();if(!title)return;const rating=$('#partRating').value.trim(),note=$('#partNote').value.trim(),w=$('#partPreviewWrap'),p=w.dataset.pending,pt=w.dataset.pendingType,pm=w.dataset.pendingMime;item.parts=Array.isArray(item.parts)?item.parts:[];if(editingPartId){const part=item.parts.find(x=>x.id===editingPartId);if(part){part.title=title;part.rating=rating;part.note=note;if(p)Object.assign(part,{media:p,mediaType:pt,mediaMime:pm})}}else item.parts.push({id:crypto.randomUUID(),title,rating,note,media:p||'',mediaType:pt||'image',mediaMime:pm||''});$('#partDialog').close();queueSave();render();renderPartsPopover();positionPartsPopover();showToast(tr('partSaved'))});
$('#tierBg').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;if(!isExternalMediaFile(f)){alert(tr('unsupportedFile'));return}if(!checkMediaSize(f,e.target))return;const info=mediaInfo(f);pendingTierBg={data:await fileToDataUrl(f),type:info.kind,mime:info.mime}});$('#clearTierBg').onclick=()=>{pendingTierBg='__CLEAR__'};
