const RU_LAT={а:'a',б:'b',в:'v',г:'g',д:'d',е:'e',ё:'yo',ж:'zh',з:'z',и:'i',й:'y',к:'k',л:'l',м:'m',н:'n',о:'o',п:'p',р:'r',с:'s',т:'t',у:'u',ф:'f',х:'h',ц:'ts',ч:'ch',ш:'sh',щ:'sch',ъ:'',ы:'y',ь:'',э:'e',ю:'yu',я:'ya'};
const KB_EN="qwertyuiop[]asdfghjkl;'zxcvbnm,.",KB_RU="йцукенгшщзхъфывапролджэячсмитьбю";
function normalizeSearchText(v){return String(v||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ё/g,'е').replace(/[^a-zа-я0-9]+/gi,' ').trim().replace(/\s+/g,' ')}
function translitRu(v){return normalizeSearchText(v).split('').map(ch=>RU_LAT[ch]??ch).join('').replace(/\s+/g,' ')}
function swapKeyboard(v,from,to){return String(v||'').toLowerCase().split('').map(ch=>{const i=from.indexOf(ch);return i>=0?to[i]:ch}).join('')}
function levenshtein(a,b){if(a===b)return 0;if(!a.length)return b.length;if(!b.length)return a.length;let prev=Array.from({length:b.length+1},(_,i)=>i),cur=new Array(b.length+1);for(let i=1;i<=a.length;i++){cur[0]=i;for(let j=1;j<=b.length;j++)cur[j]=Math.min(cur[j-1]+1,prev[j]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));[prev,cur]=[cur,prev]}return prev[b.length]}
function similarity(a,b){a=a.replace(/\s/g,'');b=b.replace(/\s/g,'');if(!a||!b)return 0;if(a.includes(b)||b.includes(a))return 1;return 1-levenshtein(a,b)/Math.max(a.length,b.length)}
