function smartMatch(item,q){if(!q)return true;const qf=searchForms(q),sources=[item?.title||'',...(item?.aliases||[]),...((item?.parts||[]).flatMap(p=>[p.title||'',p.rating||'']))],sf=[...new Set(sources.flatMap(searchForms))];for(const a of qf)for(const b of sf){if(b.includes(a)||a.includes(b))return true;const ac=a.replace(/\s/g,''),bc=b.replace(/\s/g,''),min=Math.min(ac.length,bc.length);if(min>=4&&similarity(a,b)>=(min>=8?.60:.66))return true;const at=a.split(' ').filter(Boolean),bt=b.split(' ').filter(Boolean);if(at.length>1&&at.every(x=>bt.some(y=>y.includes(x)||x.includes(y)||similarity(x,y)>=.68)))return true}return false}
function applySearch(){const q=searchInput.value.trim();$$('.card').forEach(c=>{const item=active().items[c.dataset.itemId],hit=smartMatch(item,q);c.classList.toggle('highlight',!!q&&hit);c.classList.toggle('dimmed',!!q&&!hit)})}
searchInput.addEventListener('input',applySearch);searchInput.addEventListener('keydown',e=>{if(e.key==='Escape'){searchControl.classList.remove('open');searchBtn.classList.remove('active');searchInput.value='';applySearch();searchBtn.focus()}});



