const V22_EASE='cubic-bezier(.16,1,.3,1)';
let historyUndo=[],historyRedo=[],historyBase='',historyBatch=false,historyTimer=null,historySuppressed=false,newListEntranceId=null;
function historyClone(){const c=structuredClone?structuredClone(state):JSON.parse(JSON.stringify(state));if(c.appSettings)c.appSettings.snapshots=[];return c}
function historyString(){try{return JSON.stringify(historyClone())}catch{return ''}}
function initHistory(){historyUndo=[];historyRedo=[];historyBase=historyString();historyBatch=false;updateHistoryButtons();renderSnapshotControls();applyVersionPreview(false)}
function scheduleHistoryCommit(){if(historySuppressed)return;const now=historyString();if(!historyBase){historyBase=now;return}if(now===historyBase)return;if(!historyBatch){historyUndo.push(historyBase);if(historyUndo.length>50)historyUndo.shift();historyRedo=[];historyBatch=true;updateHistoryButtons()}clearTimeout(historyTimer);historyTimer=setTimeout(()=>{historyBase=historyString();historyBatch=false;updateHistoryButtons()},560)}
const queueSaveV21=queueSave;queueSave=function(){scheduleHistoryCommit();queueSaveV21()};
