function ensureSnapshots(){state.appSettings=state.appSettings||{};state.appSettings.snapshots=Array.isArray(state.appSettings.snapshots)?state.appSettings.snapshots:[];return state.appSettings.snapshots}
function renderSnapshotControls(){const sel=$('#snapshotSelect');if(!sel)return;const arr=ensureSnapshots();sel.innerHTML='';if(!arr.length){const o=document.createElement('option');o.value='';o.textContent=tr('noSnapshot');sel.appendChild(o)}else arr.slice().reverse().forEach(s=>{const o=document.createElement('option');o.value=s.id;const d=new Date(s.createdAt);o.textContent=`${s.name} · ${d.toLocaleString()}`;sel.appendChild(o)});const has=!!arr.length;$('#snapshotRestoreBtn').disabled=!has;$('#snapshotDeleteBtn').disabled=!has}
function createSnapshot(){const l=active(),arr=ensureSnapshots(),snap={id:crypto.randomUUID(),createdAt:Date.now(),name:l.name,list:JSON.parse(JSON.stringify(l))};arr.push(snap);while(arr.length>6)arr.shift();queueSaveV21();renderSnapshotControls();showToast(tr('snapshotCreated'))}
