function applyVersionPreview(ask=true){state.appSettings=state.appSettings||{};let v=Number(state.appSettings.siteVersionPreview||0);const sel=$('#siteVersionPreview');if(sel)sel.value=String(v);const root=document.documentElement;['preview-no-notes','preview-no-search','preview-no-parts','preview-single-list','preview-no-media'].forEach(c=>root.classList.remove(c));if(!v)return;if(v<8){root.classList.add('preview-no-notes');notesOpen=false}if(v<13)root.classList.add('preview-no-search');if(v<15){root.classList.add('preview-no-parts');closePartsPopover(true);hidePartsHover(true)}if(v<3)root.classList.add('preview-single-list');if(v<5)root.classList.add('preview-no-media')}
