setCustomizerOpen=setCustomizerOpenV22;

function snapshotBackgroundV22(){const host=$('#appBackground'),canvas=document.createElement('canvas'),dpr=Math.min(2,window.devicePixelRatio||1);canvas.width=Math.max(1,Math.round(innerWidth*dpr));canvas.height=Math.max(1,Math.round(innerHeight*dpr));canvas.className='bg-transition-old-v22';canvas.style.width=innerWidth+'px';canvas.style.height=innerHeight+'px';const x=canvas.getContext('2d');x.scale(dpr,dpr);const t=active().theme;x.fillStyle=t.bg;x.fillRect(0,0,innerWidth,innerHeight);const m=host?.querySelector('.bg-media');if(m){try{const sw=m.videoWidth||m.naturalWidth||m.width,sh=m.videoHeight||m.naturalHeight||m.height;if(sw&&sh){if(active().view.stretchListBackground)x.drawImage(m,0,0,innerWidth,innerHeight);else{const sc=Math.max(innerWidth/sw,innerHeight/sh),dw=sw*sc,dh=sh*sc;x.drawImage(m,(innerWidth-dw)/2,(innerHeight-dh)/2,dw,dh)}}}catch{}}x.fillStyle=rgbaFromHex(t.bg,.74);x.fillRect(0,0,innerWidth,innerHeight);return canvas}
