  const dx=destRect.left+destRect.width/2-(r.left+r.width/2),dy=destRect.top+destRect.height/2-(r.top+r.height/2),sx=Math.max(.18,Math.min(1,destRect.width/r.width)),sy=Math.max(.18,Math.min(1,destRect.height/r.height));
