const loadV26Base=load;load=async function(){await loadV26Base();state.version=26;v26Normalize();v26EnsureAurora();v26EnsureAmbientControls();v26SyncAmbientControls();v26ApplyAurora();render();v26Prewarm()};



/* =========================
   v27 — blur guard, inspector, right rail
   ========================= */
const V27={inspectId:null,switching:false};

function v27Normalize(){
  state.version=27;
  state.lists.forEach(l=>Object.values(l.items||{}).forEach(it=>{if(typeof it.description!=='string')it.description=''}));
}

/* Item editor description support. */
const openItemV27Base=openItem;
openItem=function(id=null){
  openItemV27Base(id);
  const it=id?active().items[id]:null;
  const d=$('#itemDescription');if(d)d.value=it?.description||'';
  const lab=$('#itemDescriptionLabel');if(lab)lab.textContent=state.language==='en'?'Description':state.language==='mix'?'Описание / Description':'Описание';
};

function v27LocateText(id){
  const loc=locateItemV24(id);if(!loc)return '';
  if(loc.zone==='notes')return state.language==='en'?'Notes':'Заметки';
  if(loc.zone==='unranked')return state.language==='en'?'Unranked':'Без оценки';
  return active().tiers.find(t=>t.id===loc.zone)?.name||'';
}
function v27EnsureInspector(){
  if($('#v27ItemInspect'))return;
  const d=document.createElement('dialog');d.id='v27ItemInspect';d.className='v27-item-dialog';d.innerHTML='<div id="v27ItemInspectShell"></div>';document.body.appendChild(d);
  d.addEventListener('click',e=>{if(e.target===d)d.close()});
}
function v27InspectorButton(icon,label,cls=''){return `<button class="btn ${cls}"><span>${icon}</span><span>${esc(label)}</span></button>`}
function v27OpenInspector(id){
  const item=active().items[id];if(!item)return;V27.inspectId=id;v27EnsureInspector();
  const d=$('#v27ItemInspect'),sh=$('#v27ItemInspectShell'),loc=locateItemV24(id),inNotes=loc?.zone==='notes',parts=(item.parts||[]).length;
  sh.innerHTML='<div class="v27-item-shell"><div class="v27-item-media" id="v27ItemMedia"></div><div class="v27-item-body"><div class="v27-item-kicker">'+esc(v27LocateText(id))+'</div><div class="v27-item-title">'+esc(item.title)+'</div><div class="v27-item-desc">'+esc(item.description|| (state.language==='en'?'No description yet.':'Описание пока не добавлено.'))+'</div>'+(item.aliases?.length?'<div class="v27-item-aliases">'+esc(item.aliases.join(' · '))+'</div>':'')+'<div class="v27-item-actions" id="v27ItemActions"></div></div></div>';
  const media=item.media||placeholder(item.title),type=item.mediaType||kindFromData(media)||'image';$('#v27ItemMedia').appendChild(createMediaNode(media,type,item.mediaMime,'',false));
  const a=$('#v27ItemActions');
  a.insertAdjacentHTML('beforeend',v27InspectorButton(iconSvg('parts'),(state.language==='en'?'Parts':'Части')+(parts?` · ${parts}`:''),'v27-parts'));
  a.insertAdjacentHTML('beforeend',v27InspectorButton(iconSvg('note'),inNotes?(state.language==='en'?'In Notes':'В заметках'):(state.language==='en'?'Save to Notes':'В заметки'),'v27-item-note'+(inNotes?' active':'')));
  a.insertAdjacentHTML('beforeend',v27InspectorButton(iconSvg('edit'),state.language==='en'?'Edit':'Редактировать','v27-edit'));
  a.insertAdjacentHTML('beforeend',v27InspectorButton(iconSvg('del'),state.language==='en'?'Delete':'Удалить','v27-delete'));
  a.querySelector('.v27-parts').onclick=()=>{d.close();setTimeout(()=>{const card=document.querySelector(`.card[data-item-id="${CSS.escape(id)}"]`);togglePartsPopover(id,card||document.body)},100)};
  a.querySelector('.v27-item-note').onclick=()=>{const card=document.querySelector(`.card[data-item-id="${CSS.escape(id)}"]`);d.close();setTimeout(()=>toggleNotesV24(id,card),80)};
  a.querySelector('.v27-edit').onclick=()=>{d.close();setTimeout(()=>openItem(id),80)};
  a.querySelector('.v27-delete').onclick=()=>{const card=document.querySelector(`.card[data-item-id="${CSS.escape(id)}"]`);d.close();setTimeout(()=>deleteItem(id,card),80)};
  d.showModal();
}

/* Cards are now interaction surfaces, not miniature toolbars. */
function renderCardV27(item,zoneId){
  const card=document.createElement('div');card.className='card';card.draggable=true;card.dataset.itemId=item.id;
  const media=item.media||placeholder(item.title),type=item.mediaType||kindFromData(media)||'image';card.appendChild(createMediaNode(media,type,item.mediaMime,'media',false));
  const ov=document.createElement('div');ov.className='card-overlay';ov.innerHTML=`<div class="card-title">${esc(item.title)}</div>`;card.appendChild(ov);
  let dragStarted=false,ignoreClickUntil=0;
  card.addEventListener('mouseenter',()=>schedulePartsHover(item.id,card));card.addEventListener('mouseleave',()=>schedulePartsHoverClose());
  card.addEventListener('dragstart',e=>{dragStarted=true;hidePartsHover(true);draggedId=item.id;card.classList.add('dragging');e.dataTransfer.effectAllowed='move';try{e.dataTransfer.setData('text/plain',item.id)}catch{}});
  card.addEventListener('dragend',()=>{draggedId=null;card.classList.remove('dragging');$$('.drag-over').forEach(x=>x.classList.remove('drag-over'));ignoreClickUntil=Date.now()+220;dragStarted=false});
  card.addEventListener('click',e=>{if(dragStarted||Date.now()<ignoreClickUntil)return;e.stopPropagation();hidePartsHover(true);v27OpenInspector(item.id)});
  return card;
}
renderCard=renderCardV27;

/* Tier tools live on a stable vertical rail on the right edge. */
function renderTierV27(t,index){
  const row=document.createElement('div');row.className='tier-row';row.dataset.tierId=t.id;
  const v=active().view,n=active().tiers.length,r=Math.max(0,Number(v.tierRadius)||0),joined=!!v.mergeTierCorners&&Number(v.boardGap)===0;
  if(joined){if(n===1)row.style.borderRadius=`${r}px`;else if(index===0)row.style.borderRadius=`${r}px ${r}px 0 0`;else if(index===n-1)row.style.borderRadius=`0 0 ${r}px ${r}px`;else row.style.borderRadius='0';if(index>0)row.style.borderTopWidth='0'}
  const label=document.createElement('div');label.className='tier-label'+(t.bgMedia?' has-bg':'');label.style.background=t.color;
  if(t.bgMedia)label.appendChild(createMediaNode(t.bgMedia,t.bgType||kindFromData(t.bgMedia)||'image',t.bgMime,'tier-bg-media',true));
  const txt=document.createElement('div');txt.className='label-text';txt.textContent=t.name;label.appendChild(txt);
  const items=document.createElement('div');items.className='tier-items';items.dataset.zone=t.id;renderContainer(items,t.items,t.id);
  const ctr=document.createElement('div');ctr.className='tier-controls';ctr.dataset.noExport='';ctr.innerHTML=`<button class="icon-btn" data-a="edit">${iconSvg('edit')}</button><button class="icon-btn" data-a="up">${iconSvg('up')}</button><button class="icon-btn" data-a="down">${iconSvg('down')}</button><button class="icon-btn" data-a="del">${iconSvg('del')}</button>`;
  ctr.querySelector('[data-a="edit"]').title=tr('edit');ctr.querySelector('[data-a="up"]').title=state.language==='en'?'Move up':'Выше';ctr.querySelector('[data-a="down"]').title=state.language==='en'?'Move down':'Ниже';ctr.querySelector('[data-a="del"]').title=tr('delete');
  ctr.querySelector('[data-a="edit"]').onclick=()=>openTier(t.id);ctr.querySelector('[data-a="up"]').onclick=()=>moveTier(index,-1);ctr.querySelector('[data-a="down"]').onclick=()=>moveTier(index,1);ctr.querySelector('[data-a="del"]').onclick=()=>deleteTier(t.id);
  row.append(label,items,ctr);return row;
}
renderTier=renderTierV27;

/* Guarantee visible blur on the very first switched frame with a temporary blurred clone. */
function v27BlurGuard(){
  const src=$('#appBackground');if(!src)return null;const g=src.cloneNode(true);g.removeAttribute('id');g.className='v27-switch-blur';g.querySelectorAll('[id]').forEach(x=>x.removeAttribute('id'));
  const blur=Math.max(0,Number(active().view?.tierPanelBlur)||0);g.style.filter=`blur(${Math.max(blur,8)}px) saturate(112%)`;g.style.webkitFilter=g.style.filter;
  g.querySelectorAll('video').forEach(v=>{v.muted=true;v.loop=true;v.playsInline=true;try{v.currentTime=$('#appBackground video')?.currentTime||0}catch{};attemptPlay(v)});
  document.body.insertBefore(g,$('.app'));return g;
}
async function switchActiveListV27(id){
  if(!id||id===state.activeListId||V27.switching)return;V27.switching=true;
  const oldContent=oldContentOverlayV23(),oldBg=snapshotBackgroundV22();if(oldBg){oldBg.classList.add('v26-old-bg');document.body.appendChild(oldBg)}
  state.activeListId=id;notesOpen=false;closePartsPopover(true);hidePartsHover(true);applyAll();render();v27Normalize();v26ApplyAurora();v26SyncAmbientControls();
  const guard=v27BlurGuard();
  const live=[$('#listDescriptionView'),$('#v25Hud'),$('#board'),document.querySelector('.unranked-wrap')].filter(Boolean);live.forEach(x=>{x.style.opacity='0'});
  /* Force layout and the native backdrop while the old snapshot still covers the page. */
  live.forEach(x=>void x.offsetHeight);$$('.tier-items,.unranked,.notes-zone,.v25-hud-card').forEach(x=>{const c=getComputedStyle(x);void c.backdropFilter;void c.webkitBackdropFilter});
  await v26WaitFrames(2);
  const ease='cubic-bezier(.16,1,.3,1)',dur=520;
  live.forEach(x=>x.animate([{opacity:0},{opacity:1}],{duration:dur,easing:ease,fill:'forwards'}).finished.finally(()=>x.style.opacity=''));
  oldContent?.animate([{opacity:1},{opacity:0}],{duration:dur,easing:ease,fill:'forwards'}).finished.finally(()=>oldContent.remove());
  oldBg?.animate([{opacity:1},{opacity:0}],{duration:620,easing:ease,fill:'forwards'}).finished.finally(()=>oldBg.remove());
  if(guard)setTimeout(()=>guard.animate([{opacity:1},{opacity:0}],{duration:380,easing:'ease-out',fill:'forwards'}).finished.finally(()=>guard.remove()),520);
  setTimeout(()=>{V27.switching=false},700);queueSave();
}
switchActiveList=switchActiveListV27;

/* Put Command Center and shortcut discovery in the visible actions menu. */
