  const points=active().tiers.map((t,i)=>({n:parseFloat(String(t.name).replace(',','.')),c:t.color,i})).filter(x=>Number.isFinite(x.n));
  if(points.length<2)return active().theme.accent;points.sort((a,b)=>a.n-b.n);
  const max=points[points.length-1].n,min=points[0].n;
  if(n>max){if(n<=100&&max<=10)n=n/100*max;else if(n<=10&&max<=5)n=n/10*max}
