/* =========================
   v28 Stable — runtime corrective pass
   ========================= */
const STABLE_EASE='cubic-bezier(.16,1,.3,1)';
let stableSwitchSerial=0;

function stableTwoFrames(){return new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))}
function stableCancelAnim(el){if(el?._stableAnimation){try{el._stableAnimation.cancel()}catch{}el._stableAnimation=null}}

/* One interruptible surface motion for Notes / menus / hover previews. */
motionShow=function(el){
  if(!el)return;stableCancelAnim(el);clearTimeout(el._motionTimer);el.hidden=false;el.classList.remove('motion-in','motion-out');
  const cs=getComputedStyle(el),opacity=Math.max(0,Math.min(1,parseFloat(cs.opacity)||0));
  el.style.transformOrigin='50% 0%';
  const a=el.animate([
    {opacity:opacity||0,transform:opacity>.05?(cs.transform==='none'?'translateY(0) scale(1)':cs.transform):'translateY(-8px) scale(.985)'},
    {opacity:1,transform:'translateY(0) scale(1)'}
  ],{duration:420,easing:STABLE_EASE,fill:'forwards'});
  el._stableAnimation=a;
  a.finished.catch(()=>{}).finally(()=>{if(el._stableAnimation!==a)return;el._stableAnimation=null;el.style.opacity='';el.style.transform=''});
};
motionHide=function(el,after){
  if(!el||el.hidden){after?.();return}stableCancelAnim(el);clearTimeout(el._motionTimer);el.classList.remove('motion-in','motion-out');
  const cs=getComputedStyle(el),opacity=Math.max(0,Math.min(1,parseFloat(cs.opacity)||1));
  const a=el.animate([
    {opacity,transform:cs.transform==='none'?'translateY(0) scale(1)':cs.transform},
    {opacity:0,transform:'translateY(-7px) scale(.985)'}
  ],{duration:300,easing:STABLE_EASE,fill:'forwards'});
  el._stableAnimation=a;
  a.finished.catch(()=>{}).finally(()=>{if(el._stableAnimation!==a)return;el._stableAnimation=null;el.hidden=true;el.style.opacity='';el.style.transform='';after?.()});
};
motionToggle=function(el){if(!el)return false;if(el.hidden){motionShow(el);return true}motionHide(el);return false};

/* Customizer uses CSS grid, so it can be reversed at any moment without a height/loading phase. */
