/* Popovers/menus: blur is already present; only opacity + vertical position animate. */
motionShow=function(el){
  if(!el)return;try{el._stableAnimation?.cancel()}catch{};try{el._finalAnim?.cancel()}catch{};
  el.hidden=false;el.classList.remove('motion-in','motion-out');
  finalAnimate(el,[{opacity:0,transform:'translateY(-8px)'},{opacity:1,transform:'translateY(0)'}],{duration:360,easing:FINAL_EASE})
    .finally(()=>{if(!el.hidden){el.style.opacity='';el.style.transform=''}});
};
motionHide=function(el,after){
  if(!el||el.hidden){after?.();return}try{el._stableAnimation?.cancel()}catch{};try{el._finalAnim?.cancel()}catch{};
  finalAnimate(el,[{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(-7px)'}],{duration:240,easing:FINAL_EASE})
    .finally(()=>{el.hidden=true;el.style.opacity='';el.style.transform='';after?.()});
};
