/* Editable shortcuts in Settings. */
function bugfixCanonicalShortcut(raw){
  let s=String(raw||'').trim();if(!s)return'';
  s=s.replace(/⌘|cmd|command/ig,'Ctrl').replace(/control/ig,'Ctrl').replace(/option|alt/ig,'Alt').replace(/shift/ig,'Shift');
  const parts=s.split('+').map(x=>x.trim()).filter(Boolean),mods=[],keys=[];
  for(const p of parts){const q=p.toLowerCase();if(q==='ctrl')mods.push('Ctrl');else if(q==='shift')mods.push('Shift');else if(q==='alt')mods.push('Alt');else keys.push(p.length===1?p.toUpperCase():p)}
  return [...new Set(mods),...keys].join('+');
}
function bugfixShortcutMatches(e,raw){
  const s=bugfixCanonicalShortcut(raw);if(!s)return false;const parts=s.split('+'),wantCtrl=parts.includes('Ctrl'),wantShift=parts.includes('Shift'),wantAlt=parts.includes('Alt'),key=parts.find(x=>!['Ctrl','Shift','Alt'].includes(x));
  if(wantCtrl!==!!(e.ctrlKey||e.metaKey)||wantShift!==!!e.shiftKey||wantAlt!==!!e.altKey)return false;
  if(!wantCtrl&&(e.ctrlKey||e.metaKey)||!wantShift&&e.shiftKey||!wantAlt&&e.altKey)return false;
  return String(e.key||'').toLowerCase()===String(key||'').toLowerCase();
}
