/* Notes flight: destination is hidden synchronously before the browser can paint it.
   The destination then receives its own soft entrance after the ghost lands. */
toggleNotesV24=function(id,card){
  const item=active().items[id];if(!item||!card)return;const from=locateItemV24(id),leaving=from.zone==='notes';
  if(!leaving)item.noteOrigin={zone:from.zone,index:from.index};
  let target=leaving?(item.noteOrigin||{zone:'unranked',index:active().unranked.length}):{zone:'notes',index:active().notes.length};
  if(leaving&&target.zone!=='unranked'&&!active().tiers.some(t=>t.id===target.zone))target={zone:'unranked',index:active().unranked.length};
  const {g,r}=makeNoteGhostV24(card);card.style.opacity='0';placeItemV24(id,target);if(leaving)delete item.noteOrigin;queueSave();render();
  let dest=document.querySelector(`.card[data-item-id="${CSS.escape(id)}"]`),dr=null;
  /* Hide the newly rendered card immediately, before any RAF / paint. */
  if(dest){dest.style.opacity='0';dest.style.filter='blur(4px)';dest.style.transform='scale(.94)'}
  if(!leaving&&!notesOpen){const b=$('#notesBtn');dr=b?.getBoundingClientRect()||null;dest=null}else dr=dest?.getBoundingClientRect()||null;
  if(!dr){const b=$('#notesBtn');dr=b?.getBoundingClientRect()||r}
  animateGhostToV24(g,r,dr,()=>{if(!dest)return;const a=dest.animate([{opacity:0,transform:'scale(.94)',filter:'blur(4px)'},{opacity:1,transform:'scale(1)',filter:'blur(0px)'}],{duration:500,easing:'cubic-bezier(.16,1,.3,1)',fill:'both'});a.finished.catch(()=>{}).finally(()=>{dest.style.opacity='';dest.style.filter='';dest.style.transform=''})});
};

/* Slower Notes/menu motion, still interruptible. */
motionShow=function(el){if(!el)return;try{el._finalAnim?.cancel()}catch{};el.hidden=false;const a=el.animate([{opacity:0,transform:'translateY(-8px)'},{opacity:1,transform:'translateY(0)'}],{duration:520,easing:'cubic-bezier(.16,1,.3,1)',fill:'both'});el._finalAnim=a;a.finished.catch(()=>{}).finally(()=>{if(el._finalAnim===a){el._finalAnim=null;el.style.opacity='';el.style.transform=''}})};
motionHide=function(el,after){if(!el||el.hidden){after?.();return}try{el._finalAnim?.cancel()}catch{};const a=el.animate([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(-7px)'}],{duration:410,easing:'cubic-bezier(.16,1,.3,1)',fill:'both'});el._finalAnim=a;a.finished.catch(()=>{}).finally(()=>{if(el._finalAnim===a){el._finalAnim=null;el.hidden=true;el.style.opacity='';el.style.transform='';after?.()}})};
motionToggle=function(el){if(!el)return false;if(el.hidden){motionShow(el);return true}motionHide(el);return false};

/* Physical-key matching: N works on the same keyboard key even when the active layout emits Cyrillic Т. */
function physicalCode101(key){
  const k=String(key||'').toUpperCase();if(/^[A-Z]$/.test(k))return'Key'+k;if(/^[0-9]$/.test(k))return'Digit'+k;
  return({'/':'Slash','\\':'Backslash',',':'Comma','.':'Period',';':'Semicolon',"'":'Quote','[':'BracketLeft',']':'BracketRight','-':'Minus','=':'Equal','`':'Backquote','SPACE':'Space','ESC':'Escape','ESCAPE':'Escape'})[k]||''
}
bugfixShortcutMatches=function(e,raw){
  const s=bugfixCanonicalShortcut(raw);if(!s)return false;
  const parts=s.split('+'),wantCtrl=parts.includes('Ctrl'),wantShift=parts.includes('Shift'),wantAlt=parts.includes('Alt'),key=parts.find(x=>!['Ctrl','Shift','Alt'].includes(x));
  if(wantCtrl!==!!(e.ctrlKey||e.metaKey)||wantShift!==!!e.shiftKey||wantAlt!==!!e.altKey)return false;
  const code=physicalCode101(key);return code?e.code===code:String(e.key||'').toLowerCase()===String(key||'').toLowerCase()
};

