/* Stretch Media: one dropdown, same underlying three settings. */
function setupStretchDropdown101(){
  if(document.querySelector('.stretch-media-card'))return;const ids=['stretchCards','stretchListBackground','stretchTierBackgrounds'],nodes=ids.map(id=>$('#'+id)).filter(Boolean);if(nodes.length!==3)return;
  const oldCards=nodes.map(n=>n.closest('.setting-card'));const host=oldCards[0]?.parentElement;if(!host)return;
  const card=document.createElement('div');card.className='setting-card stretch-media-card';card.innerHTML=`<div class="setting"><label><span id="stretchMediaTitle101">Stretch Media</span></label><button type="button" class="btn stretch-media-trigger" id="stretchMediaTrigger101"><span id="stretchMediaButton101">Stretch Media</span><span class="stretch-summary" id="stretchMediaSummary101"></span><span>⌄</span></button></div><div class="stretch-media-menu" id="stretchMediaMenu101" hidden></div>`;
  host.insertBefore(card,oldCards[0]);const menu=$('#stretchMediaMenu101');
  const ru=state.language!=='en',texts=ru?['Карточки','Фон тирлиста','Фоны тиров']:['Item cards','Tier-list background','Tier backgrounds'];
  nodes.forEach((input,i)=>{const row=document.createElement('label');row.className='stretch-media-option';const span=document.createElement('span');span.textContent=texts[i];row.append(span,input);menu.appendChild(row);input.addEventListener('change',updateStretchSummary101)});oldCards.forEach(x=>x.remove());
  $('#stretchMediaTrigger101').onclick=e=>{e.stopPropagation();if(menu.hidden)motionShow(menu);else motionHide(menu)};
  document.addEventListener('click',e=>{if(!e.target.closest('.stretch-media-card')&&!menu.hidden)motionHide(menu)});updateStretchSummary101()
}
function updateStretchSummary101(){const ids=['stretchCards','stretchListBackground','stretchTierBackgrounds'],n=ids.filter(id=>$('#'+id)?.checked).length,el=$('#stretchMediaSummary101');if(el)el.textContent=state.language==='en'?`${n}/3 selected`:`Выбрано ${n}/3`}

