/* Generic custom selects for every select inside Customize. Native selects stay as the source of truth. */
const SELECT102=new WeakMap();
function closeSelect102(except=null){document.querySelectorAll('.ui-select102.open').forEach(w=>{if(w!==except){w.classList.remove('open');const m=w._menu;if(m)m.hidden=true}})}
function syncSelect102(sel){const rec=SELECT102.get(sel);if(!rec)return;const o=sel.options[sel.selectedIndex];rec.label.textContent=o?.textContent||'—';rec.menu.querySelectorAll('.ui-select102-option').forEach((b,i)=>b.classList.toggle('active',i===sel.selectedIndex))}
function positionSelect102(w){const m=w._menu,r=w.getBoundingClientRect();const width=Math.max(r.width,190);m.style.width=width+'px';let top=r.bottom+6,left=r.left;if(top+m.offsetHeight>innerHeight-10)top=Math.max(10,r.top-m.offsetHeight-6);if(left+width>innerWidth-10)left=Math.max(10,innerWidth-width-10);m.style.left=left+'px';m.style.top=top+'px'}
function enhanceSelect102(sel){if(!sel||SELECT102.has(sel)||sel.closest('#v26ToolDialog'))return;sel.classList.add('ui-select102-native');const w=document.createElement('div');w.className='ui-select102';const btn=document.createElement('button');btn.type='button';btn.className='ui-select102-btn';const label=document.createElement('span'),arrow=document.createElement('span');arrow.className='ui-select102-arrow';arrow.textContent='⌄';btn.append(label,arrow);sel.parentNode.insertBefore(w,sel);w.append(sel,btn);const menu=document.createElement('div');menu.className='ui-select102-menu';menu.hidden=true;document.body.appendChild(menu);w._menu=menu;const rebuild=()=>{menu.innerHTML='';[...sel.options].forEach((o,i)=>{if(o.hidden)return;const b=document.createElement('button');b.type='button';b.className='ui-select102-option';b.textContent=o.textContent;b.onclick=()=>{sel.selectedIndex=i;sel.dispatchEvent(new Event('change',{bubbles:true}));syncSelect102(sel);w.classList.remove('open');menu.hidden=true};menu.appendChild(b)});syncSelect102(sel)};SELECT102.set(sel,{wrap:w,btn,label,menu,rebuild});btn.onclick=e=>{e.stopPropagation();const opening=menu.hidden;closeSelect102(opening?w:null);if(opening){menu.hidden=false;w.classList.add('open');positionSelect102(w)}else{menu.hidden=true;w.classList.remove('open')}};sel.addEventListener('change',()=>syncSelect102(sel));new MutationObserver(rebuild).observe(sel,{childList:true,subtree:true,attributes:true});rebuild()}
