window.addEventListener('resize',()=>document.querySelectorAll('.ui-select102.open').forEach(positionSelect102));window.addEventListener('scroll',()=>document.querySelectorAll('.ui-select102.open').forEach(positionSelect102),true);document.addEventListener('click',e=>{if(!e.target.closest('.ui-select102')&&!e.target.closest('.ui-select102-menu'))closeSelect102()});

