/* Custom destructive confirms everywhere important. */
deleteTier=async function(id){const l=active(),t=l.tiers.find(x=>x.id===id);if(!t)return;const ru=state.language!=='en';const yes=await askConfirm101({title:ru?'Удалить тир?':'Delete tier?',text:ru?`«${t.name}» будет удалён. Его карточки перейдут в «Без оценки».`:`“${t.name}” will be deleted. Its items will move to Unranked.`,okLabel:ru?'Удалить':'Delete',cancelLabel:ru?'Отмена':'Cancel'});if(!yes)return;const row=document.querySelector(`.tier-row[data-tier-id="${CSS.escape(id)}"]`);if(!row){l.unranked.push(...t.items);l.tiers=l.tiers.filter(x=>x.id!==id);queueSave();render();return}const h=row.getBoundingClientRect().height;disintegrateElement(row,()=>{row.style.opacity='0';row.style.overflow='hidden';const a=row.animate([{height:h+'px',minHeight:h+'px',marginBottom:getComputedStyle(row).marginBottom},{height:'0px',minHeight:'0px',marginBottom:'0px',borderWidth:'0px'}],{duration:520,easing:'cubic-bezier(.16,1,.3,1)',fill:'forwards'});a.finished.catch(()=>{}).finally(()=>{l.unranked.push(...t.items);l.tiers=l.tiers.filter(x=>x.id!==id);queueSave();render()})},{cols:8,rows:3,duration:680})};
deletePart=async function(partId){const item=active().items[partsOpenItemId];if(!item)return;const part=(item.parts||[]).find(x=>x.id===partId);if(!part)return;const ru=state.language!=='en',yes=await askConfirm101({title:ru?'Удалить часть?':'Delete part?',text:ru?`«${part.title}» будет удалена.`:`“${part.title}” will be deleted.`,okLabel:ru?'Удалить':'Delete',cancelLabel:ru?'Отмена':'Cancel'});if(!yes)return;const row=document.querySelector(`.part-row[data-part-id="${CSS.escape(partId)}"]`),finish=()=>{item.parts=item.parts.filter(x=>x.id!==partId);queueSave();render();renderPartsPopover()};if(row)disintegrateElement(row,finish,{cols:5,rows:4,duration:650});else finish()};
