/* Minesweeper — Google web board sizes: 10x8/10, 18x14/40, 24x20/99. */
const MINE102={difficulty:'easy',rows:8,cols:10,mines:10,board:[],started:false,over:false,flags:0,start:0,timer:null};
const MINE_LEVELS102={easy:{rows:8,cols:10,mines:10},medium:{rows:14,cols:18,mines:40},hard:{rows:20,cols:24,mines:99}};
function ensureMine102(){let d=$('#mineDialog102');if(d)return d;d=document.createElement('dialog');d.id='mineDialog102';d.innerHTML=`<div class="mine102"><div class="mine102-head"><div><h3>Сапёр</h3><div class="status">ЛКМ — открыть · ПКМ — флаг</div></div><button class="btn small" id="mineClose102">Закрыть</button></div><div class="mine102-toolbar"><div class="mine102-diffs"><button class="btn small mine102-diff" data-d="easy">Easy</button><button class="btn small mine102-diff" data-d="medium">Medium</button><button class="btn small mine102-diff" data-d="hard">Hard</button></div><button class="btn small" id="mineReset102">Новая игра</button></div><div class="mine102-meta"><span id="mineCount102"></span><span id="mineTime102">0.0s</span><span id="mineState102"></span></div><div class="mine102-board-wrap"><div class="mine102-board" id="mineBoard102"></div></div></div>`;document.body.appendChild(d);$('#mineClose102').onclick=()=>v28CloseDialog(d);$('#mineReset102').onclick=()=>mineReset102(MINE102.difficulty);d.querySelectorAll('.mine102-diff').forEach(b=>b.onclick=()=>mineReset102(b.dataset.d));v28WireAnimatedCancel?.(d);return d}
function mineNeighbors102(r,c){const out=[];for(let y=-1;y<=1;y++)for(let x=-1;x<=1;x++){if(!x&&!y)continue;const rr=r+y,cc=c+x;if(rr>=0&&cc>=0&&rr<MINE102.rows&&cc<MINE102.cols)out.push([rr,cc])}return out}
function mineBuild102(safeR,safeC){let placed=0;while(placed<MINE102.mines){const r=Math.floor(Math.random()*MINE102.rows),c=Math.floor(Math.random()*MINE102.cols);if(MINE102.board[r][c].mine||Math.abs(r-safeR)<=1&&Math.abs(c-safeC)<=1)continue;MINE102.board[r][c].mine=true;placed++}for(let r=0;r<MINE102.rows;r++)for(let c=0;c<MINE102.cols;c++)MINE102.board[r][c].n=mineNeighbors102(r,c).filter(([rr,cc])=>MINE102.board[rr][cc].mine).length}
function mineReset102(diff='easy'){const cfg=MINE_LEVELS102[diff];Object.assign(MINE102,{difficulty:diff,rows:cfg.rows,cols:cfg.cols,mines:cfg.mines,started:false,over:false,flags:0,start:0});clearInterval(MINE102.timer);MINE102.board=Array.from({length:cfg.rows},()=>Array.from({length:cfg.cols},()=>({mine:false,n:0,open:false,flag:false})));renderMine102();const d=ensureMine102();d.querySelectorAll('.mine102-diff').forEach(b=>b.classList.toggle('active',b.dataset.d===diff));$('#mineTime102').textContent='0.0s';$('#mineState102').textContent=''}
function mineReveal102(r,c){if(MINE102.over)return;const cell=MINE102.board[r][c];if(cell.flag||cell.open)return;if(!MINE102.started){MINE102.started=true;MINE102.start=performance.now();mineBuild102(r,c);MINE102.timer=setInterval(()=>{$('#mineTime102').textContent=((performance.now()-MINE102.start)/1000).toFixed(1)+'s'},100)}cell.open=true;if(cell.mine){MINE102.over=true;clearInterval(MINE102.timer);$('#mineState102').textContent='💥';renderMine102(r,c);return}if(cell.n===0)mineNeighbors102(r,c).forEach(([rr,cc])=>mineReveal102(rr,cc));const left=MINE102.board.flat().filter(x=>!x.mine&&!x.open).length;if(left===0){MINE102.over=true;clearInterval(MINE102.timer);$('#mineState102').textContent='✓ Победа';showToast('Сапёр: победа!')}renderMine102()}
function mineFlag102(r,c){if(MINE102.over)return;const cell=MINE102.board[r][c];if(cell.open)return;cell.flag=!cell.flag;MINE102.flags+=cell.flag?1:-1;renderMine102()}
function renderMine102(boomR=-1,boomC=-1){const el=$('#mineBoard102');if(!el)return;el.style.gridTemplateColumns=`repeat(${MINE102.cols},26px)`;el.innerHTML='';for(let r=0;r<MINE102.rows;r++)for(let c=0;c<MINE102.cols;c++){const x=MINE102.board[r][c],b=document.createElement('button');b.type='button';b.className='mine102-cell';if(x.open){b.classList.add('open');if(x.mine){b.classList.add('mine');b.textContent='✹'}else if(x.n){b.classList.add('n'+x.n);b.textContent=x.n}}else if(x.flag){b.classList.add('flag');b.textContent='⚑'}if(r===boomR&&c===boomC)b.classList.add('boom');b.onclick=()=>mineReveal102(r,c);b.oncontextmenu=e=>{e.preventDefault();mineFlag102(r,c)};el.appendChild(b)}$('#mineCount102').textContent=`${Math.max(0,MINE102.mines-MINE102.flags)} mines`}
