  if(kind==='close'){tone110(650,.045,.032,'triangle',430);return}
  if(kind==='toggle'){tone110(760,.035,.040,'triangle',920);setTimeout(()=>tone110(1160,.028,.016,'sine',1050),22);return}
  if(kind==='success'){tone110(480,.065,.050,'sine',620);setTimeout(()=>tone110(720,.075,.042,'sine',900),48);setTimeout(()=>tone110(980,.095,.032,'triangle',1120),92);return}
  if(kind==='danger'){tone110(240,.085,.060,'sawtooth',145);setTimeout(()=>tone110(170,.11,.036,'triangle',95),35);return}
  if(kind==='flag'){tone110(880,.035,.036,'square',720);setTimeout(()=>tone110(560,.028,.018,'triangle',650),24);return}
  if(kind==='cell'){tone110(410,.024,.030,'triangle',500);return}
  if(kind==='drag'){tone110(310,.034,.028,'sine',390);return}
  if(kind==='drop'){tone110(440,.040,.035,'triangle',330);setTimeout(()=>tone110(690,.042,.022,'sine',760),26);return}
