document.addEventListener('input',e=>{const el=e.target;if(!(el instanceof HTMLInputElement)||el.type!=='range')return;syncRange120(el);const now=performance.now(),old=RANGE_TICK120.get(el)||0;if(now-old>32){RANGE_TICK120.set(el,now);uiSound110('tick')}},true);
