      if(old){try{old._tabAnim120?.cancel()}catch{};const a=old.animate([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(-4px)'}],{duration:140,easing:'cubic-bezier(.4,0,1,1)',fill:'both'});old._tabAnim120=a;await a.finished.catch(()=>{});if(old._tabAnim120===a){old.classList.remove('active');old.style.opacity='';old.style.transform=''}}
      next.classList.add('active');try{next._tabAnim120?.cancel()}catch{};const b=next.animate([{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:300,easing:'cubic-bezier(.16,1,.3,1)',fill:'both'});next._tabAnim120=b;b.finished.catch(()=>{}).finally(()=>{if(next._tabAnim120===b){next.style.opacity='';next.style.transform=''}});
