const APP_VERSION_124='1.2.4';
const PLAKSIK_TITLE='Плаксiк — Tier List';
try{
  if(typeof STR!=='undefined'){
    if(STR.ru) STR.ru.appTitle=PLAKSIK_TITLE;
    if(STR.en) STR.en.appTitle=PLAKSIK_TITLE;
    if(STR.mix) STR.mix.appTitle=PLAKSIK_TITLE;
  }
}catch{}

function setVersion124(){
  document.documentElement.dataset.appVersion=APP_VERSION_124;
  const b=document.querySelector('.app-version-101,.version-badge,.app-version-badge,#versionBadge101');
  if(b)b.textContent=APP_VERSION_124;
  const h=$('#appTitle');if(h)h.textContent=PLAKSIK_TITLE;
  document.title=`${PLAKSIK_TITLE} ${APP_VERSION_124}`;
}
const setVersion124Base=setVersion102;
setVersion102=function(){try{setVersion124Base?.()}catch{};setVersion124()};

function mineSnapshot124(){
  return Array.isArray(MINE102?.board)?MINE102.board.map(row=>row.map(x=>({open:!!x.open,flag:!!x.flag}))):[];
}
let mineBefore124=null;
let mineOrigin124=null;
let mineDepth124=0;

function decorateMineFlags124(){
  const board=$('#mineBoard102');if(!board)return;
  board.querySelectorAll('.mine102-cell.flag').forEach(cell=>{
    if(cell.querySelector('.mine-flag-mark124'))return;
    cell.innerHTML='<span class="mine-flag-mark124">⚑</span>';
  });
}

function animateMineDelta124(before,origin=null){
  const board=$('#mineBoard102');if(!board||!before?.length)return;
  decorateMineFlags124();
  const cells=[...board.querySelectorAll('.mine102-cell')];
  const cols=MINE102.cols||1;
  let maxDelay=0;
  cells.forEach((cell,i)=>{
    const r=Math.floor(i/cols),c=i%cols;
    const prev=before?.[r]?.[c];
    const now=MINE102.board?.[r]?.[c];
    if(!prev||!now)return;
    if(now.open&&!prev.open){
      const dist=origin?Math.abs(r-origin[0])+Math.abs(c-origin[1]):0;
      const delay=Math.min(180,dist*18);
      maxDelay=Math.max(maxDelay,delay);
      cell.style.setProperty('--mine-delay124',delay+'ms');
      cell.classList.add('mine-reveal124');
      setTimeout(()=>{cell.classList.remove('mine-reveal124');cell.style.removeProperty('--mine-delay124')},delay+520);
    }else if(now.flag&&!prev.flag){
      cell.classList.add('mine-flag124');
      setTimeout(()=>cell.classList.remove('mine-flag124'),520);
    }else if(!now.flag&&prev.flag){
      cell.classList.add('mine-unflag124');
      setTimeout(()=>cell.classList.remove('mine-unflag124'),360);
    }
  });
  if(maxDelay){board.classList.add('mine-wave124');setTimeout(()=>board.classList.remove('mine-wave124'),maxDelay+560)}
}

const mineReveal124Base=mineReveal102;
mineReveal102=function(r,c,silent=false){
  const top=!silent&&mineDepth124===0;
  if(top){mineBefore124=mineSnapshot124();mineOrigin124=[r,c]}
  mineDepth124++;
  const out=mineReveal124Base(r,c,silent);
  mineDepth124--;
  if(top){
    const before=mineBefore124,origin=mineOrigin124;mineBefore124=null;mineOrigin124=null;
    requestAnimationFrame(()=>requestAnimationFrame(()=>animateMineDelta124(before,origin)));
  }
  return out;
};

const mineFlag124Base=mineFlag102;
mineFlag102=function(r,c){
  const before=mineSnapshot124();
  const out=mineFlag124Base(r,c);
  requestAnimationFrame(()=>animateMineDelta124(before,[r,c]));
  return out;
};

const renderMine124Base=renderMine102;
renderMine102=function(...args){
  const out=renderMine124Base(...args);
  decorateMineFlags124();
  return out;
};

const applyLanguage124Base=applyLanguage;
applyLanguage=function(){
  applyLanguage124Base();
  requestAnimationFrame(setVersion124);
};
const render124Base=render;
render=function(){
  render124Base();
  requestAnimationFrame(setVersion124);
};

setVersion124();



