  zoneItems.forEach((z,i)=>{const item=l.items?.[z.id];if(!item)return;const parent=z.tier?tierMap.get(z.tier.id):root;const a=((i*2.399963229728653)% (Math.PI*2));const rr=34+((i*17)%70);const px=parent.tx+Math.cos(a)*rr,py=parent.ty+Math.sin(a)*rr;const n={id:'item:'+z.id,type:'item',label:item.title||'item',x:px,y:py,tx:px,ty:py,vx:0,vy:0,r:4.6,color:z.tier?vizColor130(z.tier.color):vizColor130(l.theme?.accent)};nodes.push(n);itemMap.set(z.id,n);edges.push([parent,n,.22]);(item.parts||[]).forEach((p,j)=>{const pa=a+(j+1)*1.37,pr=16+8*j;const q={id:'part:'+p.id,type:'part',label:p.title||'part',x:px+Math.cos(pa)*pr,y:py+Math.sin(pa)*pr,tx:px+Math.cos(pa)*pr,ty:py+Math.sin(pa)*pr,vx:0,vy:0,r:2.5,color:n.color};nodes.push(q);edges.push([n,q,.13])})});
