function ensureDestroyOverlay150(){
  let root=document.getElementById('destroy150');
  if(root) return root;
  root=document.createElement('div');
  root.id='destroy150';
  root.innerHTML=`<div class="destroy150-dim"></div><svg class="destroy150-cracks" viewBox="0 0 1000 700" preserveAspectRatio="none" aria-hidden="true"></svg><div class="destroy150-shards"></div>`;
  document.body.appendChild(root);
  return root;
}
function crackSvg150(svg){
  svg.innerHTML='';
  const paths=[
    'M500 350 L445 305 L400 265 L345 235 L300 205',
    'M500 350 L555 315 L615 285 L665 235 L725 205',
    'M500 350 L535 405 L565 455 L605 505 L645 555',
    'M500 350 L455 410 L425 465 L370 510 L330 570',
    'M445 305 L420 335 L380 345 L345 380',
    'M555 315 L590 350 L635 365 L675 400',
    'M535 405 L585 420 L625 445',
    'M455 410 L410 425 L380 460',
    'M400 265 L390 220 L360 180',
    'M615 285 L650 260 L680 225',
    'M565 455 L540 500 L525 550',
    'M425 465 L450 515 L455 565'
  ];
  const ns='http://www.w3.org/2000/svg';
  paths.forEach((d,i)=>{const p=document.createElementNS(ns,'path');p.setAttribute('d',d);p.setAttribute('class','destroy150-crack');p.style.setProperty('--i',i);svg.appendChild(p)});
}
function buildShards150(host){
  host.innerHTML='';
  const count=34;
  for(let i=0;i<count;i++){
    const a=(Math.PI*2*i/count)+(i%3)*.08;
    const r=22+(i%7)*7;
    const x=50+Math.cos(a)*r;
    const y=50+Math.sin(a)*r*.72;
    const w=8+(i%5)*4, h=8+((i*3)%5)*4;
    const el=document.createElement('i');
    el.className='destroy150-shard';
    el.style.left=`${x}%`;el.style.top=`${y}%`;el.style.width=`${w}vw`;el.style.height=`${h}vh`;
    el.style.setProperty('--rx',`${(Math.cos(a)*80)+(i%4)*18}px`);
    el.style.setProperty('--ry',`${(Math.sin(a)*70)+(i%5)*16}px`);
    el.style.setProperty('--rot',`${((i%2)?1:-1)*(12+(i%7)*8)}deg`);
    el.style.setProperty('--delay',`${(i%8)*12}ms`);
    const cut=(18+(i*7)%45);
    el.style.clipPath=`polygon(${cut}% 0,100% ${10+(i*11)%50}%,${75-(i*5)%35}% 100%,0 ${70-(i*3)%35}%)`;
    host.appendChild(el);
  }
}
function destructionSound150(stage){
  try{
    if(stage===0){tone110(185,.10,.085,'sawtooth',105);noise110(.10,.08)}
    if(stage===1){tone110(120,.18,.13,'sawtooth',55);noise110(.26,.18);setTimeout(()=>tone110(68,.32,.12,'triangle',36),80)}
    if(stage===2){tone110(48,.40,.14,'sine',28);noise110(.44,.2)}
  }catch{}
}
async function playListDestruction150(){
  const root=ensureDestroyOverlay150(),svg=root.querySelector('.destroy150-cracks'),shards=root.querySelector('.destroy150-shards');
  crackSvg150(svg);buildShards150(shards);
  root.className='active150 crack150';
  destructionSound150(0);
  await new Promise(r=>setTimeout(r,430));
  root.classList.add('crack2150');destructionSound150(1);
  await new Promise(r=>setTimeout(r,320));
  root.classList.add('shatter150');destructionSound150(2);
  const app=document.querySelector('.app');
  const appAnim=app?.animate([{opacity:1,transform:'scale(1)',filter:'none'},{opacity:.94,transform:'scale(.998)',filter:'blur(0px)'},{opacity:0,transform:'scale(.985)',filter:'blur(5px)'}],{duration:620,easing:'cubic-bezier(.16,1,.3,1)',fill:'forwards'});
  await new Promise(r=>setTimeout(r,620));
  root.classList.add('black150');
  await new Promise(r=>setTimeout(r,180));
  try{appAnim?.cancel()}catch{};
}
async function finishListDestruction150(){
  const root=ensureDestroyOverlay150(),app=document.querySelector('.app');
  if(app){app.style.opacity='0';app.style.filter='blur(4px)';app.style.transform='scale(.99)'}
  await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
  if(app){app.animate([{opacity:0,filter:'blur(4px)',transform:'scale(.99)'},{opacity:1,filter:'blur(0px)',transform:'scale(1)'}],{duration:720,easing:'cubic-bezier(.16,1,.3,1)',fill:'forwards'}).finished.finally(()=>{app.style.opacity='';app.style.filter='';app.style.transform=''})}
  root.classList.add('leave150');
  setTimeout(()=>{root.className='';root.querySelector('.destroy150-shards').innerHTML='';root.querySelector('.destroy150-cracks').innerHTML=''},760);
}
async function deleteList150(){
  if(state.lists.length===1){showToast(tr('lastList'));return}
  const l=active(),ru=state.language!=='en';
  const yes=await askConfirm101({title:ru?'Удалить тирлист?':'Delete tier list?',text:ru?`«${l.name}» будет уничтожен без возможности отменить это действие.`:`“${l.name}” will be destroyed. This action cannot be undone.`,okLabel:ru?'Уничтожить':'Destroy',cancelLabel:ru?'Отмена':'Cancel'});
  if(!yes)return;
  await playListDestruction150();
  const idx=state.lists.findIndex(x=>x.id===l.id);
  state.lists=state.lists.filter(x=>x.id!==l.id);
  state.activeListId=state.lists[Math.min(idx,state.lists.length-1)]?.id||state.lists[0].id;
  applyAll();render();queueSave();
  await finishListDestruction150();
}
const load150Base=load;
load=async function(){
  await load150Base();
  const dl=document.getElementById('deleteListBtn');if(dl)dl.onclick=deleteList150;
};


