/* Same shatter language as item/tier deletion, scaled to the full application. */
deleteList160=async function(){
  if(state.lists.length===1){showToast(tr('lastList'));return}
  const l=active(),ru=!isEn160();
  const yes=await askConfirm101({
    title:ru?'Удалить тирлист?':'Delete tier list?',
    text:ru?`Тирлист «${l.name}» будет удалён. Это действие нельзя отменить.`:`“${l.name}” will be deleted. This action cannot be undone.`,
    okLabel:ru?'Удалить':'Delete',cancelLabel:ru?'Отмена':'Cancel'
  });
  if(!yes)return;
  const app=$('.app');
  explosion161();
  await new Promise(resolve=>{
    if(!app){resolve();return}
    /* Call the proven particle engine directly so the whole app breaks exactly like items/tiers. */
    disintegrateElement(app,resolve,{cols:12,rows:8,duration:760});
  });
  await blackIn161();
  const idx=state.lists.findIndex(x=>x.id===l.id);
  state.lists=state.lists.filter(x=>x.id!==l.id);
  /* The last remaining list is the newest one in local creation order. */
  state.activeListId=state.lists[state.lists.length-1]?.id||state.lists[Math.max(0,idx-1)]?.id||state.lists[0]?.id;
  applyAll();render();queueSave();syncBrand161();syncActions160();
  await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
  await blackOut161();
};

