const APP_VERSION_180='1.8.1';
const CAT_CLICK_SOUND_170='./assets/cat-click.mp3?v=6';
const CAT_LOGOS_170=[CAT_LOGO_162,...["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"]];
