function ensureCatFlash180(){
  /* New DOM node for every click. A cancelled previous animation can never hide the new flash. */
  const prev=$('#catFlash180');if(prev)prev.remove();
  const el=document.createElement('div');el.id='catFlash180';
  el.style.visibility='visible';el.style.opacity='1';
  document.body.appendChild(el);
  return el;
}
function cancelCatImpact180(){
  CAT_IMPACT_ANIMS_180.forEach(a=>{try{a.cancel()}catch{}});
  CAT_IMPACT_ANIMS_180=[];
  const old=$('#catFlash180');if(old)old.remove();
  try{document.body.style.filter=''}catch{}
  const app=$('.app');if(app)app.style.transform='';
  const bg=$('#appBackground');if(bg)bg.style.transform='';
}
function catImpact180(){
  cancelCatImpact180();

  /* Flash is recreated each time, so rapid repeated clicks still produce a full 0.5s flash. */
  const flash=ensureCatFlash180();
  void flash.offsetWidth;
  const fa=flash.animate(
    [{opacity:1,offset:0},{opacity:1,offset:.035},{opacity:0,offset:1}],
    {duration:500,easing:'cubic-bezier(.16,1,.3,1)',fill:'forwards'}
  );
  CAT_IMPACT_ANIMS_180.push(fa);
  fa.finished.catch(()=>{}).finally(()=>{if(flash.isConnected)flash.remove()});

  /* Full-page monochrome hit, guaranteed to restart from 100% grayscale every click. */
  const gray=document.body.animate(
    [{filter:'grayscale(1)',offset:0},{filter:'grayscale(1)',offset:.03},{filter:'grayscale(0)',offset:1}],
    {duration:1000,easing:'linear',fill:'none'}
  );
  CAT_IMPACT_ANIMS_180.push(gray);

  /* Hard initial shake, then one-second recovery. */
  const shakeFrames=[
    {transform:'translate3d(0,0,0)',offset:0},
    {transform:'translate3d(-12px,6px,0) rotate(-.35deg)',offset:.055},
    {transform:'translate3d(11px,-6px,0) rotate(.32deg)',offset:.11},
    {transform:'translate3d(-9px,-4px,0) rotate(-.25deg)',offset:.18},
    {transform:'translate3d(8px,4px,0) rotate(.2deg)',offset:.26},
    {transform:'translate3d(-6px,3px,0) rotate(-.15deg)',offset:.36},
    {transform:'translate3d(5px,-2px,0) rotate(.12deg)',offset:.48},
    {transform:'translate3d(-3px,2px,0) rotate(-.08deg)',offset:.62},
    {transform:'translate3d(2px,-1px,0) rotate(.04deg)',offset:.78},
    {transform:'translate3d(0,0,0) rotate(0)',offset:1}
  ];
  const app=$('.app');
  if(app)CAT_IMPACT_ANIMS_180.push(app.animate(shakeFrames,{duration:1000,easing:'linear'}));
  const bg=$('#appBackground');
  if(bg){
    const bgFrames=shakeFrames.map(f=>({...f,transform:'scale(1.025) '+(f.transform||'translate3d(0,0,0)')}));
    CAT_IMPACT_ANIMS_180.push(bg.animate(bgFrames,{duration:1000,easing:'linear'}));
  }
}
