/* ============================================================
   LTL 1.8.3 — shorter flash + random Dark Triad popup
   ============================================================ */
const APP_VERSION_183='1.8.6';
const CAT_DARK_TRIAD_183=['data:image/png;base64,','data:image/png;base64,'];


function colorBrightness185(hex){
  let h=String(hex||'').trim().replace('#','');
  if(h.length===3)h=h.split('').map(c=>c+c).join('');
  if(!/^[0-9a-f]{6}$/i.test(h))return 0;
  const n=parseInt(h,16),r=(n>>16)&255,g=(n>>8)&255,b=n&255;
  return (r*299+g*587+b*114)/1000;
}
function themeBrightness185(){
  const t=active()?.theme||{};
  const bg=t.bg||getComputedStyle(document.documentElement).getPropertyValue('--bg').trim()||'#0f1115';
  const panel=t.panel||getComputedStyle(document.documentElement).getPropertyValue('--panel').trim()||bg;
  const panel2=t.panel2||getComputedStyle(document.documentElement).getPropertyValue('--panel2').trim()||panel;
  /* Predominant theme brightness: background matters most, panels refine Custom themes. */
  return colorBrightness185(bg)*.6+colorBrightness185(panel)*.27+colorBrightness185(panel2)*.13;
}
function darkTriadSource185(){
  /* CAT_DARK_TRIAD_183[0] is the black artwork, [1] is the white artwork. */
  return themeBrightness185()<155?CAT_DARK_TRIAD_183[1]:CAT_DARK_TRIAD_183[0];
}

function spawnDarkTriad183(){
  /* Always spawn. Artwork color depends on the current theme brightness. */
  const src=darkTriadSource185();
  const wrap=document.createElement('div');
  wrap.className='dark-triad-pop-183';
  Object.assign(wrap.style,{
    position:'fixed',zIndex:'1000012',pointerEvents:'none',userSelect:'none',
    width:'min(300px, 72vw)',height:'auto',opacity:'1',transformOrigin:'50% 50%'
  });
  const img=document.createElement('img');
  img.src=src;img.alt='';img.draggable=false;
  Object.assign(img.style,{display:'block',width:'100%',height:'auto',pointerEvents:'none',userSelect:'none'});
  wrap.appendChild(img);
  document.body.appendChild(wrap);

  const vw=window.innerWidth||document.documentElement.clientWidth||1200;
  const vh=window.innerHeight||document.documentElement.clientHeight||800;
  const rect=wrap.getBoundingClientRect();
  const maxX=Math.max(0,vw-rect.width);
  const maxY=Math.max(0,vh-rect.height);
  const x=maxX>0?Math.random()*maxX:(vw-rect.width)/2;
  const y=maxY>0?Math.random()*maxY:(vh-rect.height)/2;
  wrap.style.left=`${Math.round(x)}px`;
  wrap.style.top=`${Math.round(y)}px`;

  const jitter=[
    {transform:'translate3d(0,0,0) scale(1)',opacity:1,offset:0},
    {transform:'translate3d(-10px,6px,0) scale(1.01)',opacity:1,offset:.08},
    {transform:'translate3d(12px,-6px,0) scale(.995)',opacity:1,offset:.16},
    {transform:'translate3d(-9px,-5px,0) scale(1.01)',opacity:1,offset:.28},
    {transform:'translate3d(8px,4px,0) scale(.995)',opacity:1,offset:.42},
    {transform:'translate3d(-5px,3px,0) scale(1.005)',opacity:1,offset:.58},
    {transform:'translate3d(4px,-2px,0) scale(1)',opacity:1,offset:.74},
    {transform:'translate3d(0,0,0) scale(1)',opacity:1,offset:.75},
    {transform:'translate3d(0,0,0) scale(.82)',opacity:0,offset:1}
  ];
  const a=wrap.animate(jitter,{duration:500,easing:'linear',fill:'forwards'});
  a.finished.catch(()=>{}).finally(()=>{if(wrap.isConnected)wrap.remove()});
}

