const CREDITS_EASTER_VIDEO_185='./assets/easter-vanilla-build.mp4';
let CREDITS_EASTER_KEY_185=null;
function closeCreditsEaster185(){
  const root=$('#creditsEaster185');if(!root)return;
  root.classList.remove('open');
  const v=root.querySelector('video');if(v){try{v.pause()}catch{}}
  setTimeout(()=>{if(root.isConnected&&!root.classList.contains('open'))root.remove()},320);
  if(CREDITS_EASTER_KEY_185){document.removeEventListener('keydown',CREDITS_EASTER_KEY_185,true);CREDITS_EASTER_KEY_185=null}
}
function openCreditsEaster185(){
  closeCreditsEaster185();
  const root=document.createElement('div');root.id='creditsEaster185';root.dataset.noExport='';
  const card=document.createElement('div');card.className='credits-easter-card';
  const video=document.createElement('video');
  video.src=CREDITS_EASTER_VIDEO_185;video.controls=true;video.autoplay=true;video.playsInline=true;video.preload='metadata';
  const close=document.createElement('button');close.type='button';close.className='credits-easter-close';close.setAttribute('aria-label','Close');
  close.innerHTML='<svg viewBox="0 0 24 24"><path d="M6 6l12 12M18 6L6 18"/></svg>';
  card.append(video,close);root.appendChild(card);document.body.appendChild(root);
  close.onclick=e=>{e.stopPropagation();closeCreditsEaster185()};
  root.onclick=e=>{if(e.target===root)closeCreditsEaster185()};
  CREDITS_EASTER_KEY_185=e=>{if(e.key==='Escape'){e.preventDefault();closeCreditsEaster185()}};
  document.addEventListener('keydown',CREDITS_EASTER_KEY_185,true);
  video.addEventListener('error',()=>{try{showToast(state.language==='en'?'Easter egg video file is missing':'Файл пасхалки не найден')}catch{}});
  requestAnimationFrame(()=>requestAnimationFrame(()=>root.classList.add('open')));
  video.play().catch(()=>{});
}
const polishCredits185Base=polishCredits161;
polishCredits161=function(){
  polishCredits185Base();
  const c=$('#credits130');if(!c||c.dataset.easter185==='1')return;
  c.dataset.easter185='1';
  c.addEventListener('click',openCreditsEaster185);
  c.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openCreditsEaster185()}});
};
requestAnimationFrame(()=>polishCredits161());


