window.addEventListener('pointerdown',backgroundGesture193,{capture:true,passive:true});
window.addEventListener('touchstart',backgroundGesture193,{capture:true,passive:true});
window.addEventListener('keydown',e=>{if(!e.repeat)backgroundGesture193()},{capture:true});
