document.addEventListener('visibilitychange',()=>{if(!document.hidden&&BACKGROUND_AUDIO_ARMED_192&&musicVolume192()>0)playBackgroundMusic193()});

/* Preload immediately; actual playback still waits for user activation if required by the browser. */
requestAnimationFrame(()=>ensureBackgroundAudio193());

