/* ----- music: immediate attempt + browser-safe retry ----- */
function attemptBackgroundAutoplay195(){
  const a=ensureBackgroundAudio193();
  a.autoplay=true;
  BACKGROUND_AUDIO_ARMED_192=true;
  if(musicVolume192()<=0)return;
  playBackgroundMusic193();
}
/* Browsers can block audible autoplay. We still try on page load; if blocked,
   the existing global pointer/key listeners retry on the first interaction anywhere. */
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',attemptBackgroundAutoplay195,{once:true});
else requestAnimationFrame(attemptBackgroundAutoplay195);
