/* ----- page-turn sound for list navigation ----- */
function pageFlip195(duration=.8){
  const c=soundCtx110();if(!c)return;
  const d=Math.max(.28,Number(duration)||.8),now=c.currentTime,n=Math.max(1,Math.floor(c.sampleRate*d));
  const buf=c.createBuffer(1,n,c.sampleRate),data=buf.getChannelData(0);
  for(let i=0;i<n;i++){
    const t=i/n;
    const env=Math.sin(Math.min(1,t/.17)*Math.PI/2)*Math.pow(1-t,.72);
    const flutter=.72+.28*Math.sin(t*Math.PI*10);
    data[i]=(Math.random()*2-1)*env*flutter;
  }
  const src=c.createBufferSource(),bp=c.createBiquadFilter(),lp=c.createBiquadFilter(),g=c.createGain();
  src.buffer=buf;bp.type='bandpass';bp.frequency.setValueAtTime(2100,now);bp.frequency.exponentialRampToValueAtTime(620,now+d);bp.Q.value=.7;
  lp.type='lowpass';lp.frequency.value=4200;
  g.gain.setValueAtTime(.0001,now);g.gain.linearRampToValueAtTime(.10,now+.055);g.gain.exponentialRampToValueAtTime(.0001,now+d);
  src.connect(bp);bp.connect(lp);lp.connect(g);g.connect(SOUND110.master);src.start(now);
  /* little paper-edge snap */
  setTimeout(()=>tone110(540,.055,.018,'triangle',270),Math.max(40,(d*.43)*1000));
}

