  state.activeListId=id;notesOpen=false;closePartsPopover(true);hidePartsHover(true);applyAll();render();v27Normalize?.();v26ApplyAurora?.();v26SyncAmbientControls?.();
  await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));if(token!==switch195)return;
  await finalAnimate(c,[{opacity:.96},{opacity:0}],{duration:500,easing:FINAL_EASE});
