/* ---------- Minesweeper: preserve Easy, fit Medium/Hard inside their panel ---------- */
function fitMineBoard100(){
  const d=$('#mineDialog102'),mine=d?.querySelector('.mine102'),wrap=d?.querySelector('.mine102-board-wrap'),board=d?.querySelector('.mine102-board');
  if(!d||!mine||!wrap||!board)return;
  const diff=MINE102.difficulty||'easy',cols=MINE102.cols||10,rows=MINE102.rows||8,gap=3;
  d.classList.toggle('mine-medium100',diff==='medium');d.classList.toggle('mine-hard100',diff==='hard');
  const nominalDialog=diff==='hard'?920:780;
  const dialogW=Math.min(nominalDialog,Math.max(320,innerWidth-28));
  /* Header/toolbar/meta + gaps need roughly 205px. This cap keeps the entire dialog
     on-screen even on short windows instead of letting the grid escape its frame. */
  const maxStageW=Math.max(210,dialogW-42);
  const maxStageH=Math.max(210,innerHeight-250);
  const maxStage=Math.max(210,Math.min(maxStageW,maxStageH));
  let cell=innerWidth<720?24:28;
  /* The wrapper is square, so BOTH board axes must fit the smaller available stage axis. */
  const maxCellW=Math.floor((maxStage-24-gap*(cols-1))/cols);
  const maxCellH=Math.floor((maxStage-24-gap*(rows-1))/rows);
  cell=Math.max(10,Math.min(cell,maxCellW,maxCellH));
  board.style.setProperty('--mine-cell',cell+'px');
  board.style.setProperty('--mine-font',Math.max(8,Math.min(12,cell*.43)).toFixed(2)+'px');
  board.style.setProperty('--mine-symbol',Math.max(9,Math.min(13,cell*.46)).toFixed(2)+'px');
  board.style.gridTemplateColumns=`repeat(${cols},var(--mine-cell))`;
  const boardW=cols*cell+Math.max(0,cols-1)*gap,boardH=rows*cell+Math.max(0,rows-1)*gap;
  let side=Math.ceil(Math.max(boardW,boardH)+24);
  side=Math.min(side,maxStage);
  wrap.style.width=Math.round(side)+'px';wrap.style.height=Math.round(side)+'px';wrap.style.maxWidth='100%';
  /* Keep a little room around the larger modes by expanding the dialog itself rather
     than clipping the board. Easy remains the same 780px design. */
  d.style.width=`min(${nominalDialog}px, calc(100vw - 28px))`;
}
